"""Data models and constants for the deals package."""

from dataclasses import dataclass
from typing import Optional

STAGES = ("lead", "qualified", "proposal", "won", "lost")
TERMINAL_STAGES = {"won", "lost"}

FORECAST_WEIGHTS: dict[str, float] = {
    "lead": 0.1,
    "qualified": 0.3,
    "proposal": 0.6,
    "won": 1.0,
    "lost": 0.0,
}

@dataclass
class Contact:
    email: str
    name: Optional[str] = None

@dataclass
class Opportunity:
    id: Optional[int] = None
    contact_email: str = ""
    title: Optional[str] = None
    stage: str = "lead"
    amount: float = 0.0

"""SQLite schema and CRUD operations for the deals package."""

import csv
import os
import sqlite3
from contextlib import contextmanager
from typing import Optional

from deals.models import Contact, Opportunity, STAGES, TERMINAL_STAGES, FORECAST_WEIGHTS

DB_SCHEMA = """
CREATE TABLE IF NOT EXISTS contacts (
    email TEXT PRIMARY KEY,
    name TEXT
);
CREATE TABLE IF NOT EXISTS opportunities (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    contact_email TEXT NOT NULL,
    title TEXT,
    stage TEXT NOT NULL DEFAULT 'lead',
    amount REAL NOT NULL DEFAULT 0.0,
    FOREIGN KEY (contact_email) REFERENCES contacts(email)
);
"""


def _connect(db_path: str) -> sqlite3.Connection:
    """Open a connection to the deals database (creating it if needed)."""
    conn = sqlite3.connect(db_path)
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


@contextmanager
def get_connection(db_path: str):
    """Context manager that yields a connection and auto-commits on success."""
    conn = _connect(db_path)
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def init_db(db_path: str) -> None:
    """Create the database schema if it does not already exist."""
    with get_connection(db_path) as conn:
        conn.executescript(DB_SCHEMA)


def add_contact(db_path: str, email: str, name: Optional[str] = None) -> Contact:
    """Insert a contact. Raises sqlite3.IntegrityError if email already exists."""
    with get_connection(db_path) as conn:
        conn.execute("INSERT INTO contacts (email, name) VALUES (?, ?)", (email, name))
    return Contact(email=email, name=name)


def contact_exists(db_path: str, email: str) -> bool:
    """Return True if a contact with the given email is in the database."""
    with get_connection(db_path) as conn:
        row = conn.execute("SELECT 1 FROM contacts WHERE email = ?", (email,)).fetchone()
    return row is not None


def add_opportunity(
    db_path: str,
    contact_email: str,
    title: Optional[str] = None,
    stage: str = "lead",
    amount: float = 0.0,
) -> Opportunity:
    """Insert an opportunity. Caller must ensure contact_email exists first."""
    with get_connection(db_path) as conn:
        cur = conn.execute(
            "INSERT INTO opportunities (contact_email, title, stage, amount) VALUES (?, ?, ?, ?)",
            (contact_email, title, stage, amount),
        )
        opp_id = cur.lastrowid
    return Opportunity(id=opp_id, contact_email=contact_email, title=title, stage=stage, amount=amount)


def move_opportunity(db_path: str, opp_id: int, new_stage: str) -> Opportunity:
    """Change the stage of an opportunity. Raises ValueError if current stage is terminal."""
    with get_connection(db_path) as conn:
        row = conn.execute(
            "SELECT id, contact_email, title, stage, amount FROM opportunities WHERE id = ?",
            (opp_id,),
        ).fetchone()
        if row is None:
            raise ValueError(f"Opportunity {opp_id} not found")
        _, contact_email, title, old_stage, amount = row
        if old_stage in TERMINAL_STAGES:
            raise ValueError(f"Cannot move opportunity out of terminal stage '{old_stage}'")
        conn.execute(
            "UPDATE opportunities SET stage = ? WHERE id = ?",
            (new_stage, opp_id),
        )
    return Opportunity(id=opp_id, contact_email=contact_email, title=title, stage=new_stage, amount=amount)


def get_opportunity(db_path: str, opp_id: int) -> Optional[Opportunity]:
    """Return an opportunity by id, or None."""
    with get_connection(db_path) as conn:
        row = conn.execute(
            "SELECT id, contact_email, title, stage, amount FROM opportunities WHERE id = ?",
            (opp_id,),
        ).fetchone()
    if row is None:
        return None
    return Opportunity(id=row[0], contact_email=row[1], title=row[2], stage=row[3], amount=row[4])


def list_opportunities(db_path: str, stage: Optional[str] = None) -> list[Opportunity]:
    """Return all opportunities, optionally filtered by stage."""
    with get_connection(db_path) as conn:
        if stage is not None:
            rows = conn.execute(
                "SELECT id, contact_email, title, stage, amount FROM opportunities WHERE stage = ?",
                (stage,),
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT id, contact_email, title, stage, amount FROM opportunities"
            ).fetchall()
    return [
        Opportunity(id=r[0], contact_email=r[1], title=r[2], stage=r[3], amount=r[4])
        for r in rows
    ]


def pipeline_counts(db_path: str) -> list[tuple[str, int, float]]:
    """Return (stage, count, total_amount) for every stage in STAGES."""
    with get_connection(db_path) as conn:
        rows = conn.execute(
            "SELECT stage, COUNT(*), COALESCE(SUM(amount), 0) FROM opportunities GROUP BY stage"
        ).fetchall()
    lookup = {r[0]: (r[1], r[2]) for r in rows}
    result = []
    for s in STAGES:
        cnt, total = lookup.get(s, (0, 0.0))
        result.append((s, cnt, total))
    return result


def forecast(db_path: str) -> float:
    """Compute Σ(amount × weight) across all opportunities."""
    with get_connection(db_path) as conn:
        rows = conn.execute(
            "SELECT amount, stage FROM opportunities"
        ).fetchall()
    total = 0.0
    for amount, stage in rows:
        total += amount * FORECAST_WEIGHTS.get(stage, 0.0)
    return total

import argparse
import sys
from deals import db, export
from deals.models import STAGES, TERMINAL_STAGES, FORECAST_WEIGHTS


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="deals")
    subparsers = parser.add_subparsers(dest="command")

    # ── contact ──────────────────────────────────────────────
    contact_parser = subparsers.add_parser("contact")
    contact_sub = contact_parser.add_subparsers(dest="subcommand")
    contact_add = contact_sub.add_parser("add")
    contact_add.add_argument("--name", required=True)
    contact_add.add_argument("--email", required=True)

    # ── opp ──────────────────────────────────────────────────
    opp_parser = subparsers.add_parser("opp")
    opp_sub = opp_parser.add_subparsers(dest="subcommand")

    opp_add = opp_sub.add_parser("add")
    opp_add.add_argument("--name", required=True)
    opp_add.add_argument("--contact", required=True)
    opp_add.add_argument("--stage", default="lead", choices=STAGES)
    opp_add.add_argument("--amount", type=float, default=0.0)

    opp_move = opp_sub.add_parser("move")
    opp_move.add_argument("id", type=int)
    opp_move.add_argument("--to", dest="stage", required=True, choices=STAGES)

    # ── forecast ─────────────────────────────────────────────
    subparsers.add_parser("forecast")

    # ── pipeline ─────────────────────────────────────────────
    subparsers.add_parser("pipeline")

    # ── export ───────────────────────────────────────────────
    export_p = subparsers.add_parser("export")
    export_p.add_argument("--file", required=True)

    # ── import ───────────────────────────────────────────────
    import_p = subparsers.add_parser("import")
    import_p.add_argument("--file", required=True)

    return parser


def main() -> None:
    parser = build_parser()
    args = parser.parse_args()

    if args.command == "contact" and args.subcommand == "add":
        _handle_contact_add(args)
    elif args.command == "opp" and args.subcommand == "add":
        _handle_opp_add(args)
    elif args.command == "opp" and args.subcommand == "move":
        _handle_opp_move(args)
    elif args.command == "forecast":
        _handle_forecast()
    elif args.command == "pipeline":
        _handle_pipeline()
    elif args.command == "export":
        _handle_export(args)
    elif args.command == "import":
        _handle_import(args)
    else:
        parser.print_help()
        sys.exit(1)


def _handle_contact_add(args):
    try:
        db.add_contact(args.email, args.name)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def _handle_opp_add(args):
    try:
        db.add_opportunity(
            contact_email=args.contact,
            title=args.name,
            stage=args.stage,
            amount=args.amount,
        )
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def _handle_opp_move(args):
    try:
        db.move_opportunity(args.id, args.stage)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def _handle_forecast():
    total = db.forecast()
    print(f"{total:.2f}")


def _handle_pipeline():
    rows = db.pipeline()
    for stage, count, total_amount in rows:
        print(f"{stage}: {count} deals, ${total_amount:.2f}")


def _handle_export(args):
    export.to_csv(args.file)


def _handle_import(args):
    export.from_csv(args.file)

from deals.cli import main

if __name__ == "__main__":
    main()
